import{_ as t,o,c as r,a7 as a}from"./chunks/framework.C4ZIv4ii.js";const p=JSON.parse('{"title":"Ordering & Checkout","description":"","frontmatter":{},"headers":[],"relativePath":"wholesale/ordering.md","filePath":"wholesale/ordering.md","lastUpdated":1792170474000}'),n={name:"wholesale/ordering.md"};function s(i,e,d,l,h,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="ordering-checkout" tabindex="-1">Ordering &amp; Checkout <a class="header-anchor" href="#ordering-checkout" aria-label="Permalink to &quot;Ordering &amp; Checkout&quot;">​</a></h1><p>Everything on this page applies to wholesale customers only. Retail shoppers keep the normal cart and checkout.</p><hr><h2 id="ordering-rules" tabindex="-1">Ordering rules <a class="header-anchor" href="#ordering-rules" aria-label="Permalink to &quot;Ordering rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Where you set it</th><th>When it is checked</th></tr></thead><tbody><tr><td><strong>Minimum quantity</strong> per product</td><td>Product → Wholesale</td><td>Adding to the cart, changing the quantity, checkout</td></tr><tr><td><strong>Pack size</strong> per product (&quot;sold in packs of 12&quot;)</td><td>Product → Wholesale</td><td>The same; each cart line must be a multiple</td></tr><tr><td><strong>Maximum</strong> per product</td><td>The last quantity tier&#39;s &quot;to&quot;</td><td>The quantity box stops there and the cart refuses more</td></tr><tr><td><strong>Minimum order value</strong> per level</td><td>Wholesale → Levels</td><td>Checkout</td></tr><tr><td><strong>Minimum items</strong> per level</td><td>Wholesale → Levels</td><td>Checkout</td></tr></tbody></table><p>On the product page the quantity box opens at the product&#39;s minimum (rounded up to a whole pack) and does not go below it, and the page says <em>Minimum order: 5. Maximum order: 200.</em></p><p>Whether retail-priced extras count towards a level&#39;s minimum is up to you: <strong>Settings → Minimum order counts</strong> is <em>Everything in the cart</em> or <em>Only items at a wholesale price</em>.</p><h3 id="variable-products" tabindex="-1">Variable products <a class="header-anchor" href="#variable-products" aria-label="Permalink to &quot;Variable products&quot;">​</a></h3><p>A variable product&#39;s minimum and maximum count <strong>all its options together</strong>: with a minimum of 10, 5 red and 5 blue are enough. An option may go into the cart below the minimum; the cart says how many more are needed, and checkout holds the total to it.</p><p>To hold each option to the minimum on its own instead, tick <strong>Hold each option to the minimum and maximum on its own</strong> on the product. Pack sizes are always per cart line.</p><hr><h2 id="coupons-and-promotions" tabindex="-1">Coupons and promotions <a class="header-anchor" href="#coupons-and-promotions" aria-label="Permalink to &quot;Coupons and promotions&quot;">​</a></h2><p>Wholesale prices are already a discount, so by default:</p><ul><li><strong>No coupons on wholesale prices</strong> — wholesale customers cannot apply coupon codes;</li><li><strong>No automatic promotions on wholesale prices</strong> — &quot;buy X get Y&quot; and other <a href="/falconcms/ecommerce/promotions.html">promotions</a> do not apply, and the cart does not tell wholesale customers they qualify for one.</li></ul><p>Both are settings. A level&#39;s <strong>spend discounts</strong> still apply (see below).</p><p>The &quot;Sale!&quot; badge is not shown on a wholesale price. It stays when the retail product or variation is on sale itself.</p><hr><h2 id="payment-and-shipping-per-level" tabindex="-1">Payment and shipping per level <a class="header-anchor" href="#payment-and-shipping-per-level" aria-label="Permalink to &quot;Payment and shipping per level&quot;">​</a></h2><p>On each level (<strong>Wholesale → Levels</strong>):</p><ul><li><strong>Payment methods</strong> — untick what this level may not use. A common choice: no Cash on Delivery for distributors, only bank transfer or Pay on account.</li><li><strong>Shipping methods</strong> — the same for shipping.</li><li><strong>Free shipping from</strong> — shipping is free from this order value. The cart tells the customer how much more gets free shipping.</li></ul><p>A method you switch on later is offered until you untick it on the level. Unticking every method hides none.</p><hr><h2 id="spend-discounts" tabindex="-1">Spend discounts <a class="header-anchor" href="#spend-discounts" aria-label="Permalink to &quot;Spend discounts&quot;">​</a></h2><p>Up to three per level: &quot;<strong>X% off orders of Y or more</strong>&quot;. The biggest one reached comes off the whole order as <strong>Volume discount</strong>, on top of wholesale prices, even with promotions turned off for wholesale. The cart says how much more gets the next one.</p><hr><h2 id="deposits" tabindex="-1">Deposits <a class="header-anchor" href="#deposits" aria-label="Permalink to &quot;Deposits&quot;">​</a></h2><p>Set <strong>Deposit (%)</strong> on a level and its customers get a <strong>Pay a 30% deposit now, the rest later</strong> payment method at checkout. Tick <strong>only way to pay</strong> to make it the only method (besides Pay on account).</p><ol><li>The customer places the order. It goes <strong>on hold</strong> with the deposit and the balance recorded, and the confirmation page shows the deposit to pay and your bank details.</li><li>When the deposit arrives, click <strong>Deposit received</strong> on the admin order screen. The order moves to <strong>Processing</strong>.</li><li>When the rest arrives, click <strong>Balance received</strong>. The order is marked paid.</li></ol><p>Invoices and the portal show what is still due.</p><hr><h2 id="purchase-order-po-number" tabindex="-1">Purchase order (PO) number <a class="header-anchor" href="#purchase-order-po-number" aria-label="Permalink to &quot;Purchase order (PO) number&quot;">​</a></h2><p><strong>Settings → PO number at checkout</strong>: <em>Off</em>, <em>Optional</em> or <em>Required</em>. Wholesale customers get a <strong>Purchase order (PO) number</strong> field at checkout. It is kept on the order and shows on the admin order, the confirmation page, invoices, emails and the portal&#39;s order list.</p><hr><h2 id="tax-exemption" tabindex="-1">Tax exemption <a class="header-anchor" href="#tax-exemption" aria-label="Permalink to &quot;Tax exemption&quot;">​</a></h2><p>On a customer&#39;s screen, tick <strong>Tax exempt</strong> and enter the certificate number and, optionally, an end date. Until that date their orders carry no tax; the order records the certificate number and the invoice shows it. With prices entered including tax, the tax line goes but prices stay the same.</p><hr><h2 id="buying-on-account-credit" tabindex="-1">Buying on account (credit) <a class="header-anchor" href="#buying-on-account-credit" aria-label="Permalink to &quot;Buying on account (credit)&quot;">​</a></h2><p>Trusted customers can order now and pay later, within a credit limit.</p><p><strong>Turn it on per customer</strong> (customer screen → <strong>Credit account (buy now, pay later)</strong> → Terms): tick <strong>May buy on account</strong>, set a <strong>credit limit</strong> (empty: no limit) and <strong>days to pay</strong> (empty: the shop default in Settings). They then get a <strong>Pay on account</strong> payment method at checkout.</p><p>How it works:</p><ul><li>Each order becomes a <strong>charge</strong> on their account, due after their days to pay.</li><li>An order beyond the <strong>available credit</strong> is refused, and so is any new order on account while something is <strong>overdue</strong> (Settings → <em>Overdue accounts</em>).</li><li>You <strong>record payments</strong> (cheque, bank transfer, bKash…) and <strong>adjustments</strong> on the customer screen. A payment settles the <strong>oldest</strong> orders first and marks each one paid once it is covered.</li><li>A cancelled, failed or refunded order is reversed on the account automatically.</li><li>Customers are emailed (and texted, if SMS is on) a few days <strong>before a payment is due</strong> (Settings → <em>Remind before due</em>) and again once it is <strong>overdue</strong>. This runs daily.</li></ul><p>Customers see what they owe, their available credit, what is overdue, unpaid invoices with due dates and their statement in <strong>portal → Account &amp; invoices</strong>.</p><hr><h2 id="quotes" tabindex="-1">Quotes <a class="header-anchor" href="#quotes" aria-label="Permalink to &quot;Quotes&quot;">​</a></h2><p>For large or unusual orders, a customer can ask for your price before buying.</p><ol><li>A <strong>Request a quote</strong> button sits under the cart&#39;s checkout button (for wholesale customers, or any signed-in customer: <strong>Settings → Quote requests</strong>).</li><li>The request appears in <strong>Wholesale → Quotes</strong>. Open it, set a price per line and <strong>send</strong> it. The customer is emailed (and texted, if SMS is on).</li><li>The customer <strong>accepts</strong> it in the portal (or at <code>/wholesale/quotes</code>). Its lines go into their cart at the quoted prices and quantities, <strong>locked</strong> until they order.</li><li>Either side can <strong>decline</strong>. An expired or declined quote stops holding its prices.</li></ol><hr><h2 id="saved-lists" tabindex="-1">Saved lists <a class="header-anchor" href="#saved-lists" aria-label="Permalink to &quot;Saved lists&quot;">​</a></h2><p>Customers who order the same things often can keep a cart by name: <strong>Save this cart as a list</strong>, under the cart&#39;s checkout button. Lists belong to the whole company and live in <strong>portal → Saved lists</strong>.</p><ul><li><strong>Add to cart</strong> puts a list back in the cart at <strong>today&#39;s</strong> prices and rules.</li><li>A list can email a <strong>reorder reminder</strong> every week, 2 weeks, month or 2 months.</li></ul><hr><h2 id="order-approval" tabindex="-1">Order approval <a class="header-anchor" href="#order-approval" aria-label="Permalink to &quot;Order approval&quot;">​</a></h2><p>Company buyers&#39; orders can need the owner&#39;s approval: always, or above an amount. See <a href="/falconcms/wholesale/customers.html#order-approval-for-buyers">Order approval for buyers</a>.</p>',53)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
